import{_ as a,c as i,o as s,ae as t}from"./chunks/framework.DI6M9D4h.js";const o="/assets/kimiko-keymap-default-1.B2_rzs2O.png",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/kimiko/Keymap.md","filePath":"build-guides/kimiko/Keymap.md","lastUpdated":1754310023000}'),r={name:"build-guides/kimiko/Keymap.md"};function n(h,e,d,l,p,c){return s(),i("div",null,[...e[0]||(e[0]=[t('<h2 id="default-keymap" tabindex="-1">Default keymap <a class="header-anchor" href="#default-keymap" aria-label="Permalink to &quot;Default keymap&quot;">​</a></h2><p>The <a href="https://github.com/qmk/qmk_firmware/blob/master/keyboards/keycapsss/kimiko/keymaps/default/keymap.c" target="_blank" rel="noreferrer">default keymap</a> is laid out on the assumption that it will be used in the MacOS/US keyboard environment. Feel free to get creative and experiment with keymaps that match your preferences.</p><p><img src="'+o+'" alt="Kimiko default layout" loading="lazy"></p><h2 id="customize-the-default-keymap" tabindex="-1">Customize the default keymap <a class="header-anchor" href="#customize-the-default-keymap" aria-label="Permalink to &quot;Customize the default keymap&quot;">​</a></h2><p>This self-made keyboard use the QMK firmware, described above. The QMK firmware is highly customizable, and you can unlock a lot functionality simply by editing the keymap.</p><h3 id="edit-keymap-c-and-customize" tabindex="-1">Edit keymap.c and customize <a class="header-anchor" href="#edit-keymap-c-and-customize" aria-label="Permalink to &quot;Edit keymap.c and customize&quot;">​</a></h3><p>When customizing a keymap, start by making a copy of the <a href="https://github.com/qmk/qmk_firmware/blob/master/keyboards/keycapsss/kimiko/keymaps/default/" target="_blank" rel="noreferrer"><code>qmk_firmware/keyboards/keycapsss/kimiko/keymaps/default</code></a> folder and modifying that directory&#39;s internal <code>keymap.c</code> file. Please refer to the <a href="https://docs.qmk.fm/#/keycodes" target="_blank" rel="noreferrer">official QMK documentation</a> for the key codes and programming specifics.</p><p>After changing the keymap,</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/kimiko:default:flash</span></span></code></pre></div><p>If you get an error, please double-check the board, connection and command.</p><h3 id="bootloader" tabindex="-1">Bootloader <a class="header-anchor" href="#bootloader" aria-label="Permalink to &quot;Bootloader&quot;">​</a></h3><p><strong>Pro Micro and Puchi-C/Elite-C have different bootloader.</strong> Edit the <code>rule.mk</code> file in your keymap folder and add the following line to it.</p><h4 id="puchi-c-or-elite-c" tabindex="-1">Puchi-C or Elite-C <a class="header-anchor" href="#puchi-c-or-elite-c" aria-label="Permalink to &quot;Puchi-C or Elite-C&quot;">​</a></h4><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BOOTLOADER </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> atmel</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dfu</span></span></code></pre></div><h4 id="pro-micro" tabindex="-1">Pro Micro <a class="header-anchor" href="#pro-micro" aria-label="Permalink to &quot;Pro Micro&quot;">​</a></h4><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BOOTLOADER </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> caterina</span></span></code></pre></div><p>If you use the command <code>make keycapsss/...:flash</code>, it read the bootloader settings from the <code>rule.mk</code> and uses the right flashing software. If you don&#39;t have set the <code>BOOTLOADER</code> setting, you can change the command to <code>make keycapsss/...:caterina</code> for Pro Micro, or <code>make keycapsss/...:dfu</code> for Puchi-C/Elite-C</p><p>More information on the <a href="https://beta.docs.qmk.fm/using-qmk/guides/flashing/flashing#atmel-dfu" target="_blank" rel="noreferrer">official QMK site</a>.</p><h3 id="handedness-by-eeprom" tabindex="-1">Handedness by EEPROM <a class="header-anchor" href="#handedness-by-eeprom" aria-label="Permalink to &quot;Handedness by EEPROM&quot;">​</a></h3><p>You can tell each side of the Keyboard, whether it&#39;s left or right, by writing it into it&#39;s eeprom.<br> In order to do so, first put <code>#define EE_HANDS</code> into your config.h. Then flash the keymap with</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/kimiko:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yourkeymap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:avrdude-split-left</span></span></code></pre></div><p>and</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/kimiko:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yourkeymap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:avrdude-split-right</span></span></code></pre></div><p>respectively. If you&#39;re using DFU bootloader (in case of the Puchi-C), replace the <code>avrdude</code> with <code>dfu</code></p><p>From then on, your keyboard will know, which side they are, no matter which side you plug in. You won&#39;t have to use the flags again when flashing an update of your keymap.</p><p>If you have any problems that aren&#39;t answered here, consider joining our discord server at: (<a href="https://discord.gg/5Vfa9azMUr" target="_blank" rel="noreferrer">https://discord.gg/5Vfa9azMUr</a>)</p>',26)])])}const u=a(r,[["render",n]]);export{m as __pageData,u as default};
